// Rules whose action is executable JS rather than a construction
// template: their values are unkinded arrays outside the registry.
export const executable = {"334":true,"335":true,"448":true,"449":true,"481":true,"482":true,"483":true}

// The kinds the driver builds leaves of, one per leaf terminal.
export const leafKinds = ["statement","string","lit","num","regex","name","this","sym","schema-array"]

// ruleId → "Lhs → rhs …", for tooling (the grammar gate, the
